 out.with_suffix('.json').write_text(json.dumps(dict(file=out.name,pages=len(d),generated_on='2026-10-15',sha256=hashlib.sha256(out.read_bytes()).hexdigest(),renders=pages,visual_review_complete=False,generator='tools/build_main_cord_ic5_pdf.py'),ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
